import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let rw = conc.RwLock(3)
    let u = rw.read(|v| v * 2)
    if u == 6 {
        io.println("six")
    } else {
        io.println("other")
    }
    return Ok(())
}
